-- 177 · Catálogo contable de la organización 2 (Grupo Miraflores), de los archivos de «Parametros Hospital Miraflores»:
--   1. «3.1 CON_CUENTAS_VERSION.xls»: 2081 cuentas de las localidades 2-01 a 2-04 (versión 1). Se omite 1 fila sin
--      versión (2-02, cuenta 2010202007) que repite la misma cuenta de la versión 1.
--   2. «5. CON_OBJETOS_CONTA.xls»: 185 objetos contables.
--   3. «5.2 CON_TIPOS_TRANSACCIONES.xls» y «5.3 CON_CUENTAS_TRANSACCIONES.xls»: 1025 transacciones y 3294 líneas.
--   4. «5.1 CON_TRANSACCIONES_OBJETOS.xls»: 758 transacciones x objeto.
-- Misma lógica de los scripts 77, 78, 79 y 80 (organización 3): lo que ya existe se actualiza y lo que falta se crea.
-- Columnas que traen información y no existían:
--   transaccion_cuentas.centro_costo_anterior: CENTRO_COSTO (0 = sin centro); si el centro de costo existe en la
--   localidad, la línea queda ligada a él (centro_id). Las demás columnas ya existen (scripts 77 a 80); se repiten
--   con «if not exists».
-- Se ejecuta después del script 176. Puede ejecutarse de nuevo: la segunda vez solo actualiza.

-- ======================================================================================
-- 1. Cuentas contables
-- ======================================================================================
alter table public.cuentas add column if not exists mascara text;
alter table public.cuentas add column if not exists mostrar boolean not null default true;

do $migra$
declare
  v_org bigint;
  v_loc bigint;
  v_cat bigint;
  v_tipo bigint;
  v_mayor bigint;
  v_id bigint;
  r record;
  v_nuevas integer := 0;
  v_actualizadas integer := 0;
  v_versiones integer := 0;
  v_otra_mayor integer := 0;
  v_omitidas text := '';
begin
  select id into v_org from public.organizaciones where codigo = 2;
  if v_org is null then raise exception 'No existe la organización 2.'; end if;

  drop table if exists m_cuentas;
  create temp table m_cuentas (localidad integer, codigo text, version integer, nombre text, tipo integer, integracion text,
                               cuenta_mayor text, cuenta_anterior text, mascara text, vigente text, mostrar text) on commit drop;
