  end loop;
  perform set_config('fin.migracion', '', true);
  raise notice '%', format('Objetos contables de la organización 2: %s nuevos, %s actualizados.%s', v_nuevos, v_actualizados,
    case when v_omitidas <> '' then ' Localidades que no existen (omitidas):' || v_omitidas else '' end);
end;
$migra$;


