      (4, 9, 1049, '8100-89595-3'),
      (4, 9, 1058, '8100-89595-3'),
      (4, 9, 1059, '8100-89595-3'),
      (4, 9, 1060, '8100-89595-3'),
      (4, 9, 1061, '8100-89595-3'),
      (4, 9, 1067, '8100-89595-3'),
      (4, 9, 1068, '8100-89595-3'),
      (4, 9, 1073, '8100-89595-3'),
      (4, 9, 1074, '8100-89595-3'),
      (4, 9, 1077, '8100-89595-3'),
      (4, 9, 1086, '8100-89595-3'),
      (4, 9, 1089, '8100-89595-3'),
      (4, 9, 1179, null),
      (4, 10, 1054, null),
      (4, 10, 1072, null),
      (4, 11, 1029, null),
      (4, 11, 1030, null),
      (4, 11, 1031, null),
      (4, 11, 1045, null),
      (4, 11, 1160, null),
      (4, 12, 1035, '90-274933-2'),
      (4, 12, 1037, '90-274933-2'),
      (4, 12, 1102, '3445844132'),
      (4, 12, 1167, null),
      (4, 12, 1168, null),
      (4, 13, 1044, '90-274933-2'),
      (4, 13, 1075, '000-000000-00'),
      (4, 13, 1079, '90-285379-5'),
      (4, 13, 1081, '90-285379-5'),
      (4, 13, 1083, '8100747962'),
      (4, 13, 1180, '3445844132'),
      (4, 14, 1041, null),
      (4, 14, 1078, null),
      (4, 14, 1090, null),
      (4, 14, 1091, null),
      (4, 14, 1092, null),
      (4, 14, 1093, null),
      (4, 14, 1094, null),
      (4, 14, 1169, null),
      (4, 14, 1170, null),
      (4, 16, 1159, null),
      (4, 20, 1034, '90-274933-2'),
      (4, 20, 1036, '90-274933-2'),
      (4, 20, 1040, '90-274933-2'),
      (4, 20, 1043, '8100747962'),
      (4, 20, 1050, '90-274933-2'),
      (4, 20, 1051, null),
      (4, 20, 1057, '000-000000-00'),
      (4, 20, 1064, '000-000000-00'),
      (4, 20, 1065, '000-000000-00'),
      (4, 20, 1075, '90-285379-5'),
      (4, 20, 1079, '90-285379-5'),
      (4, 20, 1082, '90-285379-5'),
      (4, 20, 1101, '3445844132'),
      (4, 20, 1178, null),
      (4, 20, 1179, '90-274933-2'),
      (4, 27, 1023, null),
      (4, 28, 1176, null),
      (4, 47, 1175, null),
      (4, 48, 1177, null)
    ) as x (localidad, objeto, transaccion, cuenta_bancaria)
    order by localidad, objeto, transaccion
  loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.localidad;
    if v_loc is null then
      if position(format('2-%s', lpad(r.localidad::text, 2, '0')) in v_omitidas) = 0 then v_omitidas := v_omitidas || format(' 2-%s', lpad(r.localidad::text, 2, '0')); end if;
      continue;
    end if;
    select id into v_obj from public.objetos_contables where localidad_id = v_loc and numero = r.objeto;
    select id into v_trx from public.transacciones_contables where localidad_id = v_loc and numero = r.transaccion;
    if v_obj is null or v_trx is null then
      v_faltan := v_faltan || format(' 2-%s objeto %s / transacción %s;', lpad(r.localidad::text, 2, '0'), r.objeto, r.transaccion);
      continue;
    end if;
    v_banco := nullif(regexp_replace(trim(r.cuenta_bancaria), '\.+$', ''), '');
    if exists (select 1 from public.objeto_transacciones where objeto_id = v_obj and transaccion_id = v_trx) then
      update public.objeto_transacciones set cuenta_bancaria = v_banco where objeto_id = v_obj and transaccion_id = v_trx;
      v_act := v_act + 1;
    else
      insert into public.objeto_transacciones (objeto_id, transaccion_id, cuenta_bancaria) values (v_obj, v_trx, v_banco);
      v_nuevas := v_nuevas + 1;
    end if;
  end loop;

  raise notice '%', format('Transacciones x objeto de la organización 2: %s nuevas, %s actualizadas.%s%s',
    v_nuevas, v_act,
    case when v_faltan <> '' then ' Omitidas (no existe el objeto o la transacción):' || v_faltan else '' end,
    case when v_omitidas <> '' then ' Localidades que no existen (omitidas):' || v_omitidas else '' end);
end;
$migra$;

notify pgrst, 'reload schema';
